import{_ as r,B as c,c as i,o as n,at as d,j as a,F as g,C as u,G as m,w as l,t as p}from"./chunks/framework.B9WVhWzA.js";const h={class:"card-wrapper"},b=["href"],k=["src"],v={class:"title"},C=JSON.parse('{"title":"Frog UI","description":"","frontmatter":{"layout":"doc","title":"Frog UI","lastUpdated":true,"editLink":true,"navbar":true,"sidebar":true,"aside":false,"outline":"deep"},"headers":[],"relativePath":"beui/index.md","filePath":"beui/index.md"}'),_={name:"beui/index.md"},f=Object.assign(_,{setup(x){const s=[{name:"button",title:"Button",link:"button"},{name:"button_group",title:"Button Group",link:"button"},{name:"badge",title:"Badge",link:"badge"},{name:"calendar",title:"Calendar",link:"calendar"},{name:"card",title:"Card",link:"card"},{name:"checkbox",title:"Checkbox",link:"checkbox"},{name:"checkbox_group",title:"Card",link:"checkbox"},{name:"date_picker",title:"Date Picker",link:"date_picker"},{name:"form",title:"Form",link:"form"},{name:"files",title:"Files",link:"tree-list"},{name:"grid",title:"Grid",link:"grid"},{name:"input_number",title:"Input Number",link:"input-number"},{name:"input",title:"Input",link:"input"},{name:"keyboard",title:"Kbd",link:"tag"},{name:"list",title:"List",link:"list"},{name:"message",title:"Message",link:"message"},{name:"pagination",title:"Pagination",link:"pagination"},{name:"panel",title:"Panel",link:"panel"},{name:"pointing",title:"Pointing",link:"tag"},{name:"radio",title:"Radio",link:"radio"},{name:"rate",title:"Rate",link:"rate"},{name:"segment",title:"Segment",link:"segment"},{name:"selectbox",title:"Selectbox",link:"selectbox"},{name:"slider",title:"Slider",link:"slider"},{name:"switch",title:"Switch",link:"switch"},{name:"switch_button",title:"Switch Button",link:"switch"},{name:"switch_inside",title:"Switch Inide",link:"switch"},{name:"table",title:"Table",link:"table"},{name:"tabs",title:"Tabs",link:"tabs"},{name:"tag",title:"Tag",link:"tag"},{name:"tree_list",title:"Tree List",link:"tree-list"}];return(I,e)=>{const o=c("BeCard");return n(),i("div",null,[e[0]||(e[0]=d('<h1 id="frog-ui" tabindex="-1" data-v-6238273c>FROG UI <a class="header-anchor" href="#frog-ui" aria-label="Permalink to &quot;FROG UI&quot;" data-v-6238273c>​</a></h1><div class="be-segment" style="margin-top:10px;" data-v-6238273c><h1 class="header h1" data-v-6238273c>Test</h1><button class="be-button" data-v-6238273c><i class="icon left xi-document" data-v-6238273c></i> Docs <a href="https://frog-ui-css.vercel.app/" target="_blank" class="link" alt="frog ui document" data-v-6238273c></a></button><button class="be-button" data-v-6238273c><i class="icon left xi-github" data-v-6238273c></i> Github <a href="https://github.com/noistommy/ga-ui-css.git" target="_blank" class="link" alt="frog ui github" data-v-6238273c></a></button></div><h2 id="개요" tabindex="-1" data-v-6238273c>개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;" data-v-6238273c>​</a></h2><p data-v-6238273c><strong data-v-6238273c>BEUI</strong>는 SPA(React, Vue)로 제작된 Headless UI 컴포넌트 라이브러리로, 별도의 스타일을 각 컴포넌트 내에 포함하지 않고 있습니다. 대신 각 컴포넌트의 variants와 option는 디자인시스템을 이용하여 커스텀이 가능하도록 설계된 <strong data-v-6238273c>CSS 프레임워크</strong> 와 함께 사용할 수 있도록 Semantic Class Name 방식으로 개발되었습니다.</p><p data-v-6238273c><strong data-v-6238273c>Frog UI</strong> BEUI Headless UI 라이브러리에 스타일을 담당하기 위한 CSS 프레임워크입니다.</p><h2 id="frog-ui-란" tabindex="-1" data-v-6238273c>Frog UI 란? <a class="header-anchor" href="#frog-ui-란" aria-label="Permalink to &quot;Frog UI 란?&quot;" data-v-6238273c>​</a></h2><p data-v-6238273c><code data-v-6238273c>Frog</code>는 scss로 작성되며 <code data-v-6238273c>gulp</code>를 통해 빌드됩니다. 디자인 일관성을 유지하기 위해 <strong data-v-6238273c>디자인 토큰 기반의 스타일 구조</strong>를 사용하고 있으며, 이를 통해 다양한 사용자 정의 테마를 효율적으로 생성 할 수 있습니다.</p><p data-v-6238273c>먼저, 기본이 되는 스타일 요소들을 <strong data-v-6238273c>1차 토큰</strong>으로 정의하고, 이후 이 1차 토큰을 기반으로 각 엘리먼트의 스타일 요소를 구성합니다.</p><p data-v-6238273c>이러한 방식은 <strong data-v-6238273c>중복 정의를 줄이고</strong>, <strong data-v-6238273c>적은 양의 토큰만으로도 다양한 테마를 효율적으로 구성</strong>할 수 있도록 합니다.</p><h3 id="왜-frog-ui를-만들었나" tabindex="-1" data-v-6238273c>왜 Frog UI를 만들었나? <a class="header-anchor" href="#왜-frog-ui를-만들었나" aria-label="Permalink to &quot;왜 Frog UI를 만들었나?&quot;" data-v-6238273c>​</a></h3><p data-v-6238273c><strong data-v-6238273c>Frog UI</strong>는 컴포넌트 종류에 종속되지않고 독립적으로 사용 가능한 시스템 입니다.</p><p data-v-6238273c>이전까지 프로젝트 내에서 컴포넌트 라이브러리와 같이 사용 했으나 버전 관리의 어려움이 있고 프레임워크 종속성 문제로 스타일 부분만 분리해서 독립적인 빌드 시스템으로 만들게 되었습니다.</p><p data-v-6238273c>경량 스타일 프레임워크로 vue나 react등 다양한 환경에 적용 가능하며 유지 보수와 기능 확장에 유리하도록 설계되었습니다.</p><h2 id="components" tabindex="-1" data-v-6238273c>Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;" data-v-6238273c>​</a></h2>',14)),a("div",h,[(n(),i(g,null,u(s,t=>m(o,{key:t.name,image:""},{image:l(()=>[a("img",{src:`/ui-el-img/${t.name}.svg`},null,8,k)]),default:l(()=>[a("a",{class:"link",href:`https://frog-ui-css.vercel.app/pages/${t.link}`,target:"_blank"},null,8,b),a("div",v,p(t.title),1)]),_:2},1024)),64))])])}}}),F=r(f,[["__scopeId","data-v-6238273c"]]);export{C as __pageData,F as default};
